# (feastDate, name, tradition, description, patronOf) - January to April
CA = "catholic,anglican"
C = "catholic"
CO = "catholic,orthodox"
COA = "catholic,orthodox,anglican"
CPA = "catholic,protestant,anglican"

DATA = [
    ("January 1", "Mary, Mother of God", CA, "The Church begins the year honouring Mary under the oldest Marian title, Theotokos, affirmed at Ephesus in 431. Because her Son is truly God, she is truly the Mother of God.", "Mothers, the Church, peace"),
    ("January 3", "Most Holy Name of Jesus", CPA, "A feast of devotion to the name Jesus, which means 'God saves'. Saint Bernardine of Siena and the Franciscans spread the custom of invoking the Holy Name with love and reverence.", "Those seeking peace, preachers"),
    ("January 5", "Saint John Neumann", C, "Bohemian-born Redemptorist (1811-1860) who became bishop of Philadelphia. He founded the first Catholic diocesan school system in the United States and served immigrants in several languages.", "Catholic schools, immigrants"),
    ("January 7", "Saint Raymond of Penyafort", C, "Spanish Dominican canon lawyer (c. 1175-1275) who gathered the Church's decrees into one clear collection and helped Saint Peter Nolasco ransom captives. He was known for gentleness in confession.", "Canon lawyers, confessors"),
    ("January 8", "Saint Severinus of Noricum", C, "Fifth-century hermit and missionary along the Danube who fed the hungry, ransomed prisoners and comforted the people during the collapse of Roman rule. He was trusted by Romans and barbarians alike.", "Those caught in war and famine"),
    ("January 9", "Saint Adrian of Canterbury", CA, "North African abbot (d. 710) who came to England with Archbishop Theodore. His school at Canterbury taught Latin, Greek, law and Scripture and shaped the English Church for generations.", "Teachers, scholars"),
    ("January 10", "Saint Gregory of Nyssa", CA, "Bishop and theologian (c. 335-395), brother of Saint Basil and one of the three Cappadocian Fathers. He defended the Trinity at Constantinople and wrote with depth on prayer and the soul's ascent to God.", "Theologians, those who pray"),
    ("January 11", "Pope Saint Hyginus", C, "Second-century bishop of Rome who guided the Church through a time of false teaching and persecution. Tradition honours him as a martyr who defended the faith handed down from the apostles.", "Defenders of sound teaching"),
    ("January 12", "Saint Marguerite Bourgeoys", C, "French-born teacher (1620-1700) who sailed to Montreal and founded the Congregation of Notre Dame to educate children. She is a founding mother of Canada and a model of practical charity.", "Teachers, immigrants, Canada"),
    ("January 13", "Saint Hilary of Poitiers", CA, "Bishop of Gaul (c. 310-367) who resisted the Arian heresy even when exiled by the emperor. His writings on the Trinity and his hymns earned him the title Doctor of the Church.", "Defenders of the faith, those with back pain"),
    ("January 15", "Saint Paul the Hermit", COA, "Egyptian hermit (d. c. 342) honoured as the first Christian desert hermit. Tradition says Saint Anthony visited him and buried him, and that a raven brought bread to his cave each day.", "Hermits, those who seek solitude"),
    ("January 16", "Saint Berard and Companions", C, "Five Franciscans who preached in Morocco and were martyred in 1220. Their witness inspired Saint Anthony of Padua to join the Franciscan order and go to Africa.", "Missionaries, martyrs"),
    ("January 18", "Saint Prisca", C, "A young Roman woman who died for Christ in the third century. Her church on the Aventine Hill is one of the oldest in Rome, and she is among the best-loved early martyrs.", "Young people, martyrs"),
    ("January 19", "Saint Canute of Denmark", C, "King of Denmark (d. 1086) who worked to protect the Church and the poor and to strengthen justice. He was murdered at the altar in Odense and is honoured as martyr and patron of his country.", "Denmark, rulers, those who face injustice"),
    ("January 22", "Saint Vincent of Saragossa", COA, "Spanish deacon who was tortured and killed under Diocletian in 304, remaining steadfast to the end. He is one of the most widely honoured martyrs of the early Church.", "Deacons, wine-makers, those in prison"),
    ("January 23", "Saint Marianne Cope", C, "German-born American Franciscan sister (1838-1918) who went to Hawaii to care for those with leprosy on Molokai. She served for thirty years without fear and was canonized in 2012.", "People with leprosy, caregivers, outcasts"),
    ("January 25", "The Conversion of Saint Paul", CPA, "The Church remembers the moment on the road to Damascus when Christ turned the persecutor Saul into the apostle to the nations. Paul's letters form a large part of the New Testament.", "Missionaries, converts, theologians"),
    ("January 26", "Saints Timothy and Titus", CPA, "Companions of Saint Paul who became bishops in Ephesus and Crete. The letters Paul wrote to them guide pastors in the care of the Church and the example of a faithful life.", "Pastors, bishops, young leaders"),
    ("January 27", "Saint Angela Merici", C, "Italian laywoman (c. 1474-1540) who founded the Company of Saint Ursula to educate girls. Her sisters, the Ursulines, became the first teaching order of women in the Church.", "Teachers, those who educate girls"),
    ("January 29", "Saint Gildas the Wise", CA, "British monk and writer (c. 500-570) known for his sharp, moving call to repentance addressed to the kings and clergy of Britain. He lived as a hermit and teacher in Britain and Brittany.", "Historians, those who call for reform"),
    ("January 30", "Saint Hyacintha Mariscotti", C, "Italian Franciscan tertiary (1585-1640) who began religious life with little devotion but was converted by illness and prayer. She spent her later years serving the poor and the sick of Viterbo.", "The sick, converts, the poor"),

    ("February 1", "Saint Brigid of Kildare", CA, "Irish abbess (c. 451-525) who founded the monastery of Kildare and became a patroness of Ireland alongside Saint Patrick. She is remembered for generosity to the poor and hospitality to all.", "Ireland, dairy workers, scholars"),
    ("February 2", "The Presentation of the Lord", "all", "Forty days after Christmas, Mary and Joseph bring the child Jesus to the Temple, and Simeon calls him a light for the nations. Candles are blessed, which is why the feast is called Candlemas.", "Consecrated life, families"),
    ("February 4", "Saint John de Britto", C, "Portuguese Jesuit (1647-1693) who lived as an Indian ascetic in order to share the Gospel in southern India. He was beheaded for baptising a prince and is honoured as a martyr.", "Missionaries, India"),
    ("February 5", "Saint Agatha", COA, "Young Sicilian woman martyred in Catania around 251 for refusing to renounce Christ. Her courage under torture made her one of the most beloved virgin martyrs. Bread is blessed on her feast.", "Nurses, breast cancer patients, bell-founders"),
    ("February 7", "Blessed Pius IX", C, "Pope (1792-1878) with the longest confirmed pontificate in the Church's history, from 1846 to 1878. He defined the dogma of the Immaculate Conception and convened the First Vatican Council.", "Pastors, the Church in times of trial"),
    ("February 9", "Saint Apollonia", COA, "Elderly deaconess of Alexandria who had her teeth broken during a persecution around 249 and chose death rather than deny Christ. She is invoked against toothache and dental troubles.", "Dentists, those with toothache"),
    ("February 12", "Saint Meletius of Antioch", CO, "Bishop of Antioch (d. 381) who suffered exile for his orthodox faith and presided over the Council of Constantinople. He was widely loved for his gentleness while the Church was divided.", "Peacemakers, bishops"),
    ("February 13", "Saint Catherine de' Ricci", C, "Florentine Dominican nun (1522-1590) who spent twelve years in weekly ecstatic meditation on the Passion. She was also a skilled administrator, trusted advisor and friend to saints.", "The sick, mystics"),
    ("February 15", "Saint Claude de la Colombière", C, "French Jesuit (1641-1682) who became the spiritual director of Saint Margaret Mary Alacoque and promoted devotion to the Sacred Heart of Jesus, trusting his own life to divine providence.", "Spiritual directors, those devoted to the Sacred Heart"),
    ("February 16", "Saint Juliana of Nicomedia", CO, "Young woman martyred around 304 after refusing to marry a pagan official or to give up her faith. Tradition says she endured prison and torture with serene patience.", "Those facing pressure to abandon their faith"),
    ("February 17", "The Seven Holy Founders of the Servite Order", C, "Seven Florentine merchants who withdrew to Monte Senario in 1233 to live in prayer and devotion to Our Lady of Sorrows. They founded the Servants of Mary.", "Religious communities, those who mourn"),
    ("February 19", "Saint Conrad of Piacenza", C, "Italian nobleman (1290-1351) who accidentally set a fire while hunting, accepted blame and gave away his wealth. He lived as a hermit in Sicily, famed for prayer and healing.", "Hermits, those with hernias, the repentant"),
    ("February 20", "Saints Jacinta and Francisco Marto", C, "Two Portuguese shepherd children who saw Our Lady at Fatima in 1917. They died young, in 1919 and 1920, after offering their sufferings for sinners, and were canonized in 2017.", "Children, those who pray for sinners"),
    ("February 21", "Saint Peter Damian", C, "Italian monk and cardinal (1007-1072) who worked to reform the clergy and encouraged a life of simple, penitential prayer. He was named a Doctor of the Church for his writings.", "Reformers, monks, those who seek humility"),
    ("February 22", "The Chair of Saint Peter", C, "A feast celebrating the ministry of Peter as shepherd of the Church. The empty 'chair' stands for the teaching authority entrusted to Peter and his successors.", "The Pope, the unity of the Church"),
    ("February 24", "The Finding of the Head of Saint John the Baptist", "orthodox", "A feast recalling the discovery of the relic of the head of John the Baptist, the forerunner who prepared the way for Christ with the call to repentance.", "Those who repent, preachers"),
    ("February 25", "Saint Walburga", CA, "English abbess (c. 710-779) who went with her brothers to Germany to help Saint Boniface and led the double monastery of Heidenheim. She is invoked for healing.", "Sailors, crops, those seeking healing"),
    ("February 26", "Saint Porphyry of Gaza", CO, "Bishop of Gaza (c. 347-420) who stayed firm in a city where most people remained pagan. He worked patiently for conversions and cared for the poor of his diocese.", "Pastors in hostile environments"),
    ("February 28", "Pope Saint Hilarius", C, "Pope from 461 to 468 who defended the unity of the Church, upheld the teaching of Chalcedon and cared for the poor of Rome during troubled years.", "Defenders of church unity"),
    ("February 29", "Saint Oswald of Worcester", CA, "Archbishop of York (d. 992) who helped renew monastic life in England, founded the abbey of Ramsey and was loved for humility and care for the poor.", "Monks, reformers, the poor"),

    ("March 1", "Saint David of Wales", CA, "Sixth-century bishop and abbot who founded monasteries across Wales and lived a life of simplicity and prayer. His last words, 'Be joyful, keep the faith', are still quoted in Wales.", "Wales, poets, those seeking joy"),
    ("March 2", "Saint Chad of Lichfield", CA, "Seventh-century English bishop who walked the countryside to preach, a student of Saint Aidan. As bishop of Lichfield he served humbly and was loved by his flock.", "Missionaries, those who walk long roads"),
    ("March 4", "Saint Casimir of Poland", C, "Polish prince (1458-1484) who gave his wealth to the poor, preferred prayer to power, and chose chastity and a simple life. He died of illness at 25 and is a patron of Poland and Lithuania.", "Young people, Poland, Lithuania"),
    ("March 5", "Saint Piran of Cornwall", CA, "Irish-born abbot (d. c. 480) who settled in Cornwall and taught the people to farm and to love Christ. Tradition says he rediscovered tin smelting. He is honoured as patron of Cornwall.", "Cornwall, tin miners"),
    ("March 6", "Saint Colette", C, "French Poor Clare nun (1381-1447) who reformed her order, restoring the strict poverty of Saint Clare and founding many convents across Europe.", "Reformers, those who seek renewal in the Church"),
    ("March 9", "Saint Frances of Rome", C, "Roman noblewoman (1384-1440) who cared for the poor and the sick during plague and war, and founded a community of oblates. She is said to have had a guardian angel always visible to her.", "Wives, widows, drivers"),
    ("March 10", "Saint John Ogilvie", C, "Scottish Jesuit (1579-1615) who returned to a hostile Scotland to minister secretly to Catholics. He was arrested and hanged in Glasgow, and is Scotland's only canonized post-Reformation saint.", "Scotland, those who suffer for conscience"),
    ("March 11", "Saint Eulogius of Cordoba", C, "Priest and writer in Moorish Spain who encouraged Christians facing persecution. He was beheaded in 859 for sheltering a young woman who had converted to Christianity.", "Persecuted Christians, writers"),
    ("March 12", "Saint Maximilian of Tebessa", C, "A young North African who refused military service in 295 because of his faith. The Roman proconsul sentenced him to death and he went to his execution with joy.", "Conscientious objectors"),
    ("March 13", "Saint Euphrasia", CO, "Fifth-century virgin who lived in a convent in Egypt and led a life of obedient service and fasting. She was esteemed for humility and gentleness.", "Those who seek simplicity"),
    ("March 14", "Saint Matilda of Ringelheim", C, "Queen of Germany (c. 895-968), mother of Emperor Otto the Great. Widowed, she devoted herself to charity and prayer, founded monasteries, and cared for the poor.", "Widows, queens, large families"),
    ("March 15", "Saint Louise de Marillac", C, "French widow (1591-1660) who co-founded the Daughters of Charity with Saint Vincent de Paul, teaching her sisters to see Christ in the poor and the sick.", "Social workers, widows"),
    ("March 16", "Saint Heribert of Cologne", C, "Archbishop of Cologne (c. 970-1021) who was chancellor to Emperor Otto III. He was known for justice, generosity to the poor, and for ending a drought through prayer.", "Rain, those in authority"),
    ("March 20", "Saint Cuthbert of Lindisfarne", CA, "Northumbrian monk and bishop (c. 634-687) who walked the hills teaching the poor and later lived as a hermit on Farne Island. His body was carried by monks through northern England.", "Northern England, shepherds, sailors"),
    ("March 22", "Saint Nicholas Owen", C, "English Jesuit lay brother (d. 1606) who built hiding places for priests during the persecution of Catholics. Arrested and tortured to death, he never revealed those he protected.", "Craftsmen, escapees, the persecuted"),
    ("March 23", "Saint Turibius of Mogrovejo", C, "Spanish lawyer who became archbishop of Lima (1538-1606). He crossed his enormous diocese on foot, learned native languages, and defended the Indigenous people from abuse.", "Latin American bishops, those who serve the poor"),
    ("March 24", "Saint Oscar Romero", CA, "Archbishop of San Salvador (1917-1980) who spoke for the poor and condemned violence during El Salvador's civil war. He was shot while celebrating Mass and canonized in 2018.", "El Salvador, defenders of justice, the poor"),
    ("March 25", "The Annunciation of the Lord", "all", "The angel Gabriel tells Mary that she will bear the Son of God, and she answers 'let it be done to me according to your word'. The feast falls nine months before Christmas.", "Mothers, those who say yes to God"),
    ("March 26", "Saint Ludger", C, "Frisian bishop (c. 742-809) who preached in Saxony, founded the monastery of Werden and became the first bishop of Munster. Charlemagne trusted him with the mission to the Saxons.", "Missionaries, Germany"),
    ("March 27", "Saint Rupert of Salzburg", C, "Bishop and missionary (c. 660-718) in Bavaria who founded the church of Salzburg and the monastery of Saint Peter. He is honoured as apostle of Bavaria and Austria.", "Salzburg, salt miners"),
    ("March 28", "Pope Saint Sixtus III", C, "Pope from 432 to 440 who built the basilica of Saint Mary Major in Rome after the Council of Ephesus affirmed Mary as Mother of God. He worked for peace between the churches of East and West.", "Peacemakers, builders of churches"),
    ("March 29", "Saint Berthold of Calabria", C, "Crusader and hermit who settled on Mount Carmel in the twelfth century with a small group of companions. He is traditionally counted as the first superior of the Carmelite order.", "Carmelites, hermits"),
    ("March 31", "Saint Benjamin the Deacon", CO, "Persian deacon martyred in 424 after refusing to stop preaching the Gospel when released from prison. His fearless witness and gentleness are recalled in the Eastern and Western Churches.", "Deacons, those who speak the truth in danger"),

    ("April 2", "Saint Francis of Paola", C, "Italian hermit (1416-1507) who founded the Minim friars, devoted to humility, penance and charity. He advised kings and the poor alike and is a patron of seafarers.", "Sailors, the Minim friars"),
    ("April 3", "Saint Richard of Chichester", CA, "English bishop (1197-1253) who served his flock faithfully despite royal opposition. He gave generously to the poor and is remembered for the prayer 'to know Thee more clearly, love Thee more dearly'.", "Bishops, coachmen, those who seek to know Christ"),
    ("April 4", "Saint Isidore of Seville", C, "Spanish bishop (c. 560-636) and scholar who wrote an encyclopedia of knowledge, preserving ancient learning for the Middle Ages. He is named a Doctor of the Church.", "Scholars, students, the internet"),
    ("April 5", "Saint Vincent Ferrer", C, "Spanish Dominican (1350-1419) who preached across Europe, calling many to conversion. He helped to end the Western Schism and worked tirelessly for peace.", "Preachers, builders, reconcilers"),
    ("April 6", "Blessed Michael Rua", C, "First successor of Saint John Bosco (1837-1910) as head of the Salesians. He extended the order across continents and kept alive the spirit of joyful service to young people.", "Young people, Salesians"),
    ("April 7", "Saint John Baptist de La Salle", C, "French priest (1651-1719) who founded the Brothers of the Christian Schools and created methods of teaching that shaped modern education. He gave his fortune to educate poor boys.", "Teachers, school principals"),
    ("April 8", "Saint Julie Billiart", C, "French religious (1751-1816) who overcame years of paralysis to found the Sisters of Notre Dame de Namur and dedicate her life to educating girls. She is known for joyful trust in God.", "Those who are ill, teachers, the disabled"),
    ("April 10", "Saint Fulbert of Chartres", C, "Bishop of Chartres (c. 960-1028) who rebuilt his cathedral after a fire and made its school a centre of learning. He wrote letters and hymns and promoted devotion to Mary.", "Teachers, builders"),
    ("April 11", "Saint Stanislaus of Krakow", C, "Bishop of Krakow (1030-1079) who rebuked the king for his injustice and was killed while celebrating Mass. He is Poland's patron saint and a witness to the Church's moral voice.", "Poland, Krakow, those who speak for justice"),
    ("April 12", "Saint Zeno of Verona", C, "Bishop of Verona (d. c. 371) who taught clearly and gently, baptised many converts and protected the poor. His sermons survive and show a kind-hearted pastor.", "Anglers, bishops"),
    ("April 13", "Pope Saint Martin I", CO, "Pope (d. 655) who condemned an error about Christ's will and was arrested by the emperor, mistreated and exiled to Crimea. He is honoured as the last pope to die as a martyr.", "Those who suffer for the truth"),
    ("April 14", "Saint Lidwina of Schiedam", C, "Dutch woman (1380-1433) who, after a skating accident, was bedridden for 38 years. She united her sufferings to Christ and became a model of patience and a counsellor to many.", "The chronically ill, ice skaters"),
    ("April 15", "Saint Damien of Molokai", CA, "Belgian priest (1840-1889) who volunteered to live with people with leprosy in Hawaii, building homes and churches. He contracted the disease himself and died serving them.", "People with leprosy, outcasts, Hawaii"),
    ("April 17", "Pope Saint Anicetus", C, "Second-century bishop of Rome who met with Saint Polycarp to discuss the date of Easter and remained in friendship despite differences. He held firm against false teaching.", "Peacemakers, those who seek unity"),
    ("April 18", "Saint Apollonius the Apologist", C, "Roman senator martyred in about 185 after publicly defending the Christian faith before the Senate. His reasoned defence made him an early model of Christian intellectual witness.", "Lawyers, defenders of the faith"),
    ("April 19", "Pope Saint Leo IX", C, "German pope (1002-1054) who worked tirelessly to reform the Church, fight corruption and renew the clergy. He travelled widely across Europe as pope.", "Reformers, travellers"),
    ("April 20", "Saint Agnes of Montepulciano", C, "Italian Dominican (1268-1317) who entered a convent at 14 and became abbess at 20. She founded a monastery and was known for deep prayer and the gift of healing.", "Prayerful abbesses, those with illness"),
    ("April 22", "Saints Soter and Caius", C, "Two second- and third-century popes who led the Church of Rome through persecution. Soter wrote to Corinth with great compassion; Caius served at a time of fierce trials.", "Pastors in hard times"),
    ("April 24", "Saint Fidelis of Sigmaringen", C, "German lawyer turned Capuchin friar (1577-1622) who preached to Protestants in Switzerland and was martyred by a mob. He was known for kindness toward the poor.", "Lawyers, defenders of the faith"),
    ("April 26", "Pope Saint Cletus", C, "Early successor of Saint Peter as bishop of Rome, listed in the Roman Canon of the Mass. Little is known about him, but the Church honours him as an apostolic father.", "Bishops, apostolic succession"),
    ("April 27", "Saint Zita of Lucca", C, "Italian domestic servant (c. 1212-1272) who worked faithfully for one family all her life, giving to the poor from what she received. Her cheerful service made her beloved.", "Domestic workers, housekeepers"),
    ("April 30", "Pope Saint Pius V", C, "Dominican pope (1504-1572) who implemented the reforms of the Council of Trent, standardised the Roman Missal and encouraged the Rosary. He lived simply and cared for the poor.", "Reformers, Rosary devotion"),
]
